using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Existing 500K documents use "Discriminator". Preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityName|Key" to just the key value.
            // Existing documents have id = "Product|123". Preserve the old format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 breaking change #3: HasIndex() now throws for Cosmos (was a no-op before).
            // Removed the HasIndex call — Cosmos indexes are managed via indexing policy, not EF.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; } = string.Empty;
}

